  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "Solifenacin had an absolute oral bioavailability of 88% (95% CI 75.8–102.1) after 10 mg oral vs IV in healthy male volunteers, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "LSD had an absolute oral bioavailability of 80–81% in humans comparing oral to IV, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Encainide had an absolute oral bioavailability of 32 ± 7% in normal subjects after oral vs IV, still above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All supplied evidence molecules have numeric absolute or systemic oral bioavailability values at or above 20%, with representative values from 32% to 88%; therefore the prediction is high.",
  "evidence_gaps": [
    "Some records report wide interindividual ranges that dip below 20% (e.g., encainide 7–82%, sulpiride 10–70%), but central/mean values remain above threshold.",
    "A qualitative 'low bioavailability' report for encainide in some patients conflicts with numeric absolute data in normal subjects, adding minor uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

